// msg.payload is the full CSV file content read by the File In node.
function parseCsvLine(line) {
    var cols = [];
    var inQ = false;
    var cur = '';
    for (var i = 0; i < line.length; i++) {
        var ch = line[i];
        if (ch === '"') {
            // Handle escaped double quote "" inside a quoted field
            if (inQ && line[i + 1] === '"') {
                cur += '"';
                i++;
            } else {
                inQ = !inQ;
            }
        } else if (ch === ',' && !inQ) {
            cols.push(cur);
            cur = '';
        } else {
            cur += ch;
        }
    }
    cols.push(cur);
    return cols;
}

try {
    var content = String(msg.payload || '');
    var lines = content.split(/\r?\n/);
    if (lines.length < 2) {
        throw new Error('CSV file is empty or missing data rows');
    }

    var headers = parseCsvLine(lines[0]);
    var data = {};

    for (var i = 1; i < lines.length; i++) {
        var line = lines[i];
        if (!line || !line.trim()) continue;
        var cols = parseCsvLine(line);
        var row = {};
        for (var j = 0; j < headers.length; j++) {
            row[headers[j]] = (cols[j] !== undefined) ? cols[j] : '';
        }
        var pn = parseInt(row['Packet Number']);
        if (!isNaN(pn)) data[pn] = row;
    }

    flow.set('csvData', data);
    node.status({fill:'green', shape:'dot', text:'Loaded ' + Object.keys(data).length + ' packets'});
} catch(e) {
    node.error('CSV load failed: ' + e.message);
    node.status({fill:'red', shape:'ring', text:'Load failed'});
}
return null;

flow.set('id_counter', 0);
flow.set('received_count', 0);
flow.set('stop_generation', false);
flow.set('outgoing_cost_rows', []);   
flow.set('outgoing_cost_idx', {});   
msg.payload  = 'No.,ID,TIMESTAMP\n';
msg.filename = './challenge3_output/id_log.csv';
return msg;

flow.set('filtered_counter', 0);
msg.payload  = 'No.,Timestamp,Sequence Number,Attribute,Status,Data Type,Data Value\n';
msg.filename = './challenge3_output/filtered_elems.csv';
return msg;

if (flow.get('stop_generation') === true) {
    node.status({fill:'red', shape:'ring', text:'Stopped after 200 received messages'});
    return null;
} //if the flow is stoped, color red and print stopped

var id = Math.floor(Math.random() * 30001); //we generate a random number between 0 and 30k -->floor(..) elps to round down the int
var ts  = Math.floor(Date.now() / 1000); //creates the current time UNIX in s
msg.payload = JSON.stringify({id: id, timestamp: ts}); //here we create the content of the MQTT msg
msg._id = id;
msg._ts = ts;
return msg;

//here the node add a new row to id_log.csv each time that a new id is generated
var counter = flow.get('id_counter') || 0; //I need id_counter to remember how many rows I have already written
counter++;
flow.set('id_counter', counter);
msg.payload  = counter + ',' + msg._id + ',' + msg._ts + '\n'; //what to write
msg.filename = './challenge3_output/id_log.csv' ; //here I tell the node where to write the info
return msg;

if (flow.get('stop_generation') === true) {
    return [null, null];
}

var count = flow.get('received_count') || 0;
count++;
flow.set('received_count', count);
node.status({fill:'blue', shape:'dot', text: count + ' / 200'});

if (count > 200) {
    flow.set('stop_generation', true);
    node.status({fill:'red', shape:'dot', text:'STOPPED - 200 reached'});
    return [null, null];
}

var isLast = (count === 200);

// Branch finalize will start always on the 200th, indipendently from parse of the payload
var finalizeMsg = isLast ? {payload: 'finalize_after_200'} : null;
if (isLast) {
    flow.set('stop_generation', true);
}

var data;
try {
    data = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    node.warn('Invalid JSON received on challenge3/id_generator: ' + e.message);
    return [null, finalizeMsg];
}

msg._sub_id    = Number(data.id);
msg._sub_ts    = data.timestamp;
msg._msg_count = count;
msg._is_last   = isLast;

return [msg, finalizeMsg];

//i will search through packets
var csvData = flow.get('csvData');
if (!csvData) {
    node.error('csvData not loaded.');
    return null;
}
var row = csvData[msg._N];
if (!row) {
    node.warn('Packet ' + msg._N + ' not found');
    return null;
}
msg._row = row;
return msg;

var cs      = msg._row['Command String'] || '';
var pktType = msg._row['Packet Type']    || '';
if (cs.indexOf('Layer ZBEE_ZCL') !== -1) {
    msg._type = 'zbee_zcl';
} else if (pktType.indexOf('Link Status') !== -1) {
    msg._type = 'link_status';
} else {
    msg._type = 'ignore';
}
return msg;

var row = msg._row;
var cs  = row['Command String'];
var ts  = Math.floor(Date.now() / 1000);

var topicName = 'ZigBee/' + row['Device Name ZigBee Source'];

var payload = {
    timestamp:    ts,
    id:           msg._sub_id,
    'wpan.src':   row['Source Address'],
    'wpan.dst':   row['Destination Address'],
    'zbee.src':   row['Source Address ZigBee'],
    'zbee.dst':   row['Destination Address ZigBee'],
    topic:        topicName,
    payload:      cs
};

// The MQTT out node has an empty topic, so it uses this dynamic msg.topic.
msg.topic   = topicName;
msg.payload = JSON.stringify(payload);
msg._pub_ts = ts;

// Parse Command String (Python dict literals -> JSON)
try {
    var jsStr = cs.replace(/'/g, '"')
                  .replace(/\bTrue\b/g,  'true')
                  .replace(/\bFalse\b/g, 'false')
                  .replace(/\bNone\b/g,  'null');
    msg._cmd = JSON.parse(jsStr);
} catch(e) {
    msg._cmd = {};
}

return msg;

// Replaces: func_check_power_attrs
// we drop packets that don't have the status
var cmd = msg._cmd || {};
var ts  = msg._pub_ts || Math.floor(Date.now() / 1000);

var attrs     = cmd['Attribute'] || [];
if (typeof attrs     === 'string') attrs     = [attrs];

var statuses  = cmd['Status']    || [];
if (typeof statuses  === 'string') statuses  = [statuses];

var dataTypes = cmd['Data Type'] || [];
if (typeof dataTypes === 'string') dataTypes = [dataTypes];

var seq = (cmd['Sequence Number'] !== undefined) ? cmd['Sequence Number'] : '';

// HARD FILTER: only Read Attributes Response has all the camps (Attribute, Status, Data Type, Value).
//drop Read Attributes (0x00), Report Attributes (0x0a), Default Response (0x0b).
if (attrs.length === 0 || statuses.length === 0 || dataTypes.length === 0) {
    return [null, null, null];
}

var typeFields = ['Int16', 'Uint16'];
var typeLists  = {};
for (var f = 0; f < typeFields.length; f++) {
    var tf = typeFields[f];
    if (cmd[tf] !== undefined) {
        typeLists[tf] = Array.isArray(cmd[tf]) ? cmd[tf] : [cmd[tf]];
    }
}
var typeCounters = {};

function fieldForDtype(dtypeStr) {
    var dl = dtypeStr.toLowerCase();
    if (dl.indexOf('16-bit signed')   !== -1) return 'Int16';
    if (dl.indexOf('16-bit unsigned') !== -1) return 'Uint16';
    return null;
}

function getVal(dtypeStr) {
    var field = fieldForDtype(dtypeStr);
    if (!field || !typeLists[field]) return {ok: false};
    var idx = typeCounters[field] || 0;
    typeCounters[field] = idx + 1;
    var raw = typeLists[field][idx];
    if (raw === undefined) return {ok: false};
    return {ok: true, val: String(raw).split(' (')[0]};
}

var targetKws = ['RMS Current', 'RMS Voltage', 'Active Power'];
var powerRows = [];

for (var i = 0; i < attrs.length; i++) {
    var attr  = attrs[i];
    var dtype = dataTypes[i];
    var status = statuses[i];

    // counter for position-matching
    var v = (dtype !== undefined) ? getVal(dtype) : {ok: false};

    // Per-attribute completeness check
    if (status === undefined || dtype === undefined || !v.ok) {
        continue;
    }

    var isTarget = false;
    for (var t = 0; t < targetKws.length; t++) {
        if (attr.indexOf(targetKws[t]) !== -1) { isTarget = true; break; }
    }
    if (!isTarget) continue;

    powerRows.push({
        ts:     ts,
        seq:    seq,
        attr:   attr.split(' (')[0],
        status: status.split(' (')[0],
        dtype:  dtype.split(' (')[0],
        val:    v.val
    });
}

if (powerRows.length === 0) {
    return [null, null, null];
}

var voltMsg = null, currMsg = null;
for (var r = 0; r < powerRows.length; r++) {
    var pr = powerRows[r];
    if (pr.attr === 'RMS Voltage') {
        voltMsg = {payload: parseFloat(pr.val) || 0, topic: 'RMS Voltage'};
    } else if (pr.attr === 'RMS Current') {
        currMsg = {payload: parseFloat(pr.val) || 0, topic: 'RMS Current'};
    }
}

return [{payload: powerRows}, voltMsg, currMsg];

var rows    = msg.payload;
var counter = flow.get('filtered_counter') || 0;
var lines   = '';

function csvSafe(x) {
    if (x === undefined || x === null) return '';
    var s = String(x);
    if (s.indexOf(',') !== -1 || s.indexOf('\n') !== -1 || s.indexOf('\"') !== -1) {
        s = '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
}

for (var r = 0; r < rows.length; r++) {
    var pr = rows[r];
    counter++;
    lines += counter + ',' +
             pr.ts + ',' +
             csvSafe(pr.seq) + ',' +
             csvSafe(pr.attr) + ',' +
             csvSafe(pr.status) + ',' +
             csvSafe(pr.dtype) + ',' +
             csvSafe(pr.val) + '\n';
}
flow.set('filtered_counter', counter);
msg.payload  = lines;
msg.filename = './challenge3_output/filtered_elems.csv';
return msg;

// it preserves the order of arrival
// 
// Strategy-> we use an ARRAY of rows to preserve the order of arrivals 
// each row is : {src, dst, cost}. when we recieve a link that wants to update an existing link
//we leave the number untouched and simply update the cost

var row = msg._row;
var cs  = row['Command String'];
var src = String(row['Source Address ZigBee'] || '').trim().toLowerCase();

try {
    var jsStr = cs.replace(/'/g, '"')
                  .replace(/\bTrue\b/g,  'true')
                  .replace(/\bFalse\b/g, 'false')
                  .replace(/\bNone\b/g,  'null');
    var cmd = JSON.parse(jsStr);

    // Array of rows { src, dst, cost }
    var costRows = flow.get('outgoing_cost_rows') || [];

    // Index for lookup veloce: "src|dst" -> indice nella array
    var idx = flow.get('outgoing_cost_idx') || {};

    var links = cmd['Links'] || [];
    if (!Array.isArray(links)) links = [links];

    for (var i = 0; i < links.length; i++) {
        var dst = String(links[i]['Address'] || '').trim().toLowerCase();
        var cost = Number(links[i]['Outgoing Cost']);
        if (!dst || isNaN(cost)) continue;

        var key = src + '|' + dst;
        if (idx[key] !== undefined) {
            // update only the cost, position preserved
            costRows[idx[key]].cost = cost;
        } else {
            costRows.push({ src: src, dst: dst, cost: cost });
            idx[key] = costRows.length - 1;
        }
    }

    flow.set('outgoing_cost_rows', costRows);
    flow.set('outgoing_cost_idx',  idx);
} catch(e) {
    node.warn('Link Status parse error: ' + e.message);
}
return null;

// we order only for ThingSpeak.

var costRows = flow.get('outgoing_cost_rows') || [];

function hexVal(x) {
    return parseInt(String(x).trim(), 16);
}

// CSV written based on the arrival order (no reordering)
var lines = 'No.,Source,Destination,Cost\n';
for (var i = 0; i < costRows.length; i++) {
    var r = costRows[i];
    lines += (i + 1) + ',' + r.src + ',' + r.dst + ',' + r.cost + '\n';
}

var csvMsg = {
    payload: lines,
    filename: './challenge3_output/outgoing_cost.csv'
};
node.status({fill:'green', shape:'dot', text:'outgoing_cost.csv ready (' + costRows.length + ' rows)'});

// for ThingSpeak: smallest source + dest ascending hex 
if (costRows.length === 0) {
    node.warn('No link status data collected. outgoing_cost.csv has only the header.');
    return [csvMsg, null];
}

// find the smallest source (treat as hex)
var sourcesSeen = {};
for (var s = 0; s < costRows.length; s++) {
    sourcesSeen[costRows[s].src] = true;
}
var srcList = Object.keys(sourcesSeen);
srcList.sort(function(a, b) { return hexVal(a) - hexVal(b); });
var smallestSrc = srcList[0];

// all the rows of the smallestSrc ordered for dest hex ascending
var rowsForSmallest = costRows.filter(function(r) { return r.src === smallestSrc; });
rowsForSmallest.sort(function(a, b) { return hexVal(a.dst) - hexVal(b.dst); });

var sequence = [];
for (var j = 0; j < rowsForSmallest.length; j++) {
    sequence.push({ dst: rowsForSmallest[j].dst, cost: rowsForSmallest[j].cost });
}

var tsMsg = {payload: sequence, _smallest_src: smallestSrc};
return [csvMsg, tsMsg];

// Each item in the sequence becomes its own msg
// The delay node downstream passes exactly 1 message every 20 seconds
var sequence = msg.payload;

for (var i = 0; i < sequence.length; i++) {
    var item = sequence[i];
    node.send({
        payload: item.cost,
        _dst: item.dst,
        url: 'https://api.thingspeak.com/update?api_key=YOUR_THINGSPEAK_WRITE_API_KEY&field1=' + item.cost //used my personal API write key 
    });
}

return null;
